+#!/usr/bin/env bash
+set -euo pipefail
+TDF_SOCIAL_ROOT=$(cd "$(dirname "$0")/../.." && pwd)
+TDF_SOCIAL_CONTAINER="tdf-social-verification-$$"
+if [ "${TDF_SOCIAL_NATIVE:-0}" = 1 ]; then
+  TDF_SOCIAL_PG_BIN=${TDF_SOCIAL_PG_BIN:-/usr/local/opt/postgresql@16/bin}
+  TDF_SOCIAL_PG_DATA=$(mktemp -d)
